const b = $json.body ?? $json;
const lat = Number(b.latitude);
const lon = Number(b.longitude);
const hasLocation = Number.isFinite(lat) && Number.isFinite(lon) && Math.abs(lat) <= 90 && Math.abs(lon) <= 180;
const description = String(b.description ?? '').trim();
if (!description || description.length < 3) throw new Error('description_required');
if (b.location_shared === true && !hasLocation) throw new Error('valid_location_required');
const text = `${b.type ?? ''} ${description}`.toLowerCase();
let level = 'bajo';
if (/persona.*ayuda|atrapad|aislad|vivienda.*inund|desborde|puente.*colaps|herid/.test(text)) level = 'alto';
if (/urgente|peligro.*vida|niño.*atrap|adulto.*mayor.*ayuda/.test(text)) level = 'critico';
const id = `REP-${Date.now().toString(36).toUpperCase()}`;
return [{json: {
  public_code: id, type: String(b.type ?? 'otro'), description, district: String(b.district ?? 'Piura'), sector: b.sector ? String(b.sector) : null,
  latitude: hasLocation && b.location_shared === true ? lat : null, longitude: hasLocation && b.location_shared === true ? lon : null,
  location_shared: hasLocation && b.location_shared === true, people_needing_help: b.people_needing_help === true,
  reporter_id: b.reporter_id ?? null, synthetic: b.synthetic === true, source: 'citizen', hazard_level: level,
  consent_id: b.consent_id ?? null, received_at: new Date().toISOString(),
  safety_note: 'No publicar ni despachar sin validación humana.'
}}];

const base = $('Validar consentimiento y clasificar').first().json;
const raw = $json;
let ai = null;
try { ai = raw.choices?.[0]?.message?.content ? JSON.parse(raw.choices[0].message.content) : null; } catch (_) {}
const valid = ai && typeof ai.confidence === 'number' && typeof ai.abstained === 'boolean' && Array.isArray(ai.missing);
const useAi = valid;
const confidence = useAi ? Math.max(0, Math.min(1, ai.confidence)) : null;
return [{json: {...base, ai_used: useAi, ai_provider: useAi ? 'DeepSeek' : null, ai_model: useAi ? ($env.DEEPSEEK_MODEL || 'deepseek-chat') : null, ai_type: useAi ? ai.type : null, ai_sector: useAi ? ai.sector : null, confidence, abstained: useAi ? ai.abstained || confidence < 0.70 : true, missing: useAi ? ai.missing : ['validacion_ia'], rationale: useAi ? ai.rationale : 'Fallback RULES-ONLY: requiere revision humana', evidence_status: useAi ? 'IA_ASISTIDA_PENDIENTE_REVISION' : 'RULES_ONLY_PENDIENTE_REVISION'}}];
